    receive() external payable {}

    function run(address _newOwner) public {
        address oldOwner = c.owner(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.transferOwnership(_newOwner); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
